def is_valid(board):
    n = len(board)
    for i in range(n):
        for j in range(i+1, n):
            if board[i] == board[j] or abs(board[i] - board[j]) == j - i:
                return False
    return True

# Standard construction for N=11
n = 11
# Since 11 mod 6 = 5, use even then odd
board = list(range(0, n, 2)) + list(range(1, n, 2))
print("Board:", board)
print("Valid?", is_valid(board))

def verify(board):
    n = len(board)
    for i in range(n):
        for j in range(i+1, n):
            if board[i] == board[j]:
                print(f"Same column: rows {i} and {j}, col {board[i]}")
                return False
            if abs(board[i] - board[j]) == j - i:
                print(f"Same diagonal: rows {i} and {j}, cols {board[i]} and {board[j]}")
                return False
    return True

board = [0,2,4,6,8,10,1,3,5,7,9]
print("Valid:", verify(board))
print("Board:", board)
# Also print as 11x11 grid
for r in range(11):
    row = ['.'] * 11
    row[board[r]] = 'Q'
    print(' '.join(row))

# Let's also verify using python-constraint or just brute force check all constraints
board = [0,2,4,6,8,10,1,3,5,7,9]
n = 11
# Check all pairs
ok = True
for i in range(n):
    for j in range(i+1, n):
        if board[i] == board[j] or abs(board[i] - board[j]) == j - i:
            ok = False
            print(f"Conflict: ({i},{board[i]}) vs ({j},{board[j]})")
            break
    if not ok:
        break
if ok:
    print("Solution is valid")
else:
    print("Solution invalid")
